-- Demo data, idempotent: every row is inserted only when its id is absent.

INSERT INTO users (id, email, password_hash, full_name, role, active, created_at, updated_at, version)
SELECT CAST('00000000-0000-0000-0000-000000000001' AS UUID), 'usuario@test.com', '{bcrypt}$2a$10$DzQ3ZQ/uYbJGfFHwwUxmxuCVrxEdesjiadRWwNrN1MGZNj7J8iHYG', 'Usuario Demo', 'USER', TRUE,
       TIMESTAMP WITH TIME ZONE '2026-11-01 10:00:00+00', TIMESTAMP WITH TIME ZONE '2026-11-01 10:00:00+00', 0
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = CAST('00000000-0000-0000-0000-000000000001' AS UUID));

INSERT INTO users (id, email, password_hash, full_name, role, active, created_at, updated_at, version)
SELECT CAST('00000000-0000-0000-0000-000000000002' AS UUID), 'admin@test.com', '{bcrypt}$2a$10$Fnp.bbti2jWKCqzNUJlQ4ezkzBI3xwooEyAc/oPH6OI6Pdpb6O276', 'Admin Demo', 'ADMIN', TRUE,
       TIMESTAMP WITH TIME ZONE '2026-11-01 10:00:00+00', TIMESTAMP WITH TIME ZONE '2026-11-01 10:00:00+00', 0
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = CAST('00000000-0000-0000-0000-000000000002' AS UUID));

